const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const roi = ee.Geometry.Polygon([[
    [-91.6, 33.0], [-91.6, 31.2], [-90.5, 31.2], 
    [-90.5, 33.0], [-91.6, 33.0]
  ]]); // Bounding box covering the three cities

  const dates2017 = ['2017-03-19', '2017-03-26']; // 1-week window
  const dates2019 = ['2019-03-19', '2019-03-26']; // 1-week window

  // 2. Data Acquisition - Use JRC Global Surface Water for water detection
  // JRC provides water occurrence (0-100) for each pixel
  const jrcCollection = ee.ImageCollection('JRC/GSW1_3/YearlyHistory');

  // Get images for 2017 and 2019 (JRC data is yearly)
  const img2017 = jrcCollection.filter(ee.Filter.calendarRange(2017, 2017, 'year')).first();
  const img2019 = jrcCollection.filter(ee.Filter.calendarRange(2019, 2019, 'year')).first();

  // Check if images exist
  const count2017 = img2017 ? 1 : 0;
  const count2019 = img2019 ? 1 : 0;

  console.log(`2017 Images: ${count2017}, 2019 Images: ${count2019}`);

  if (count2017 === 0 || count2019 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Extract water pixels (class 3 = permanent water)
  // JRC classes: 0=no data, 1=not water, 2=seasonal water, 3=permanent water
  const waterMask2017 = img2017.select('waterClass').eq(3);
  const waterMask2019 = img2019.select('waterClass').eq(3);

  // 4. Calculate water extent (pixel count)
  const stats2017 = waterMask2017.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2019 = waterMask2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 1000,
    maxPixels: 1e9
  });

  const waterPixels2017 = stats2017.get('waterClass').getInfo();
  const waterPixels2019 = stats2019.get('waterClass').getInfo();

  console.log(`2017 Water Pixels: ${waterPixels2017}`);
  console.log(`2019 Water Pixels: ${waterPixels2019}`);

  // 5. Validation & Final Answer
  if (waterPixels2017 === null || waterPixels2019 === null || 
      isNaN(waterPixels2017) || isNaN(waterPixels2019)) {
    console.log('<answer>C3</answer>');
  } else if (waterPixels2017 === 0 || waterPixels2019 === 0) {
    console.log('<answer>C2</answer>');
  } else if (waterPixels2019 > waterPixels2017) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
